#!/usr/bin/env node
/**
 * Copy Cloudflare Pages Functions to dist/ so cloudflare/pages-action
 * (which only uploads dist/) can deploy them. Without this script,
 * /api/* endpoints silently 404 in production because the root
 * functions/ directory never reaches the Pages deployment.
 *
 * Also patches dist/_routes.json (generated by @astrojs/cloudflare) to
 * include /api/* in the "include" array — otherwise CF Pages routes
 * /api/* requests to the static asset handler and 404s. Astro's auto-
 * generated _routes.json omits /api/* when output is 'static'.
 *
 * Run automatically via `npm run build:cf` (used by deploy.yml).
 * Idempotent — safe to run on every build.
 */
import { cp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const src = resolve(root, "functions");
const dst = resolve(root, "dist/functions");
const distRoutes = resolve(root, "dist/_routes.json");

if (!existsSync(src)) {
  console.log("copy-functions: no functions/ directory, skipping");
  process.exit(0);
}

if (!existsSync(resolve(root, "dist"))) {
  console.error("copy-functions: dist/ does not exist — run `astro build` first");
  process.exit(1);
}

// 1) Copy functions/ → dist/functions/
await rm(dst, { recursive: true, force: true });
await mkdir(resolve(root, "dist"), { recursive: true });
await cp(src, dst, { recursive: true });
console.log(`copy-functions: copied ${src} → ${dst}`);

// 2) Patch dist/_routes.json — add /api/* to "include" so Pages routes
//    /api/* requests to Functions instead of static asset handler.
if (existsSync(distRoutes)) {
  const raw = await readFile(distRoutes, "utf8");
  const routes = JSON.parse(raw);
  routes.include = Array.isArray(routes.include) ? routes.include : [];
  if (!routes.include.includes("/api/*")) {
    routes.include.unshift("/api/*");
  }
  await writeFile(distRoutes, JSON.stringify(routes, null, 2) + "\n");
  console.log(`copy-functions: patched dist/_routes.json → include: ${JSON.stringify(routes.include)}`);
} else {
  console.warn("copy-functions: dist/_routes.json missing — /api/* may 404");
}
